// 2. Closure Leaks
function createLeak() {
  const largeData = new Array(1000000).fill('data');
  return function() {
    console.log(largeData.length); // Captures largeData
  };
}

// Fix: Minimize closure scope
function createOptimized() {
  const largeData = new Array(1000000).fill('data');
  const summary = largeData.length;
  return function() {
    console.log(summary); // Only keep needed data
  };
}

